/* Hand-written explanations of the REAL repository (snapshot in repo-data.js).
   Every note is tied to a line range AND an "anchor" (text that must appear on
   the first line). If the code changes and the anchor is no longer found, the
   app marks the note as "not verified for this version".

   Note format: [fromLine, toLine, "anchor text", `what it does`, `why it exists`, {extra}]
   extra keys: i = inputs, o = outputs, d = depends on, s = how to say it, w = warning / issue
*/
window.KB = {};

KB.layers = [
  { id: "entry", name: "Entry points", color: "#0a84ff", files: ["main.py", "gui_main.py"],
    plain: "Where the program starts. Each one builds the objects and starts a loop." },
  { id: "ui", name: "User interface (menus & windows)", color: "#bf5af2",
    files: ["admin_system/admin_menu.py", "student_system/student_menu.py", "student_system/enrolment_menu.py",
            "gui_system/login_window.py", "gui_system/enrolment_window.py", "gui_system/subject_window.py", "gui_system/exception_window.py"],
    plain: "Talks to the user: asks for input, prints results, shows windows. Little or no business logic." },
  { id: "logic", name: "Controllers (logic)", color: "#ff9f0a",
    files: ["admin_system/admin_controller.py", "student_system/student_controller.py", "student_system/enrolment_controller.py"],
    plain: "Does the real work: validation, login, enrolment rules, grouping, partitioning." },
  { id: "model", name: "Models (data classes)", color: "#30d158", files: ["models/student.py", "models/subject.py"],
    plain: "Describe what a Student and a Subject are, and convert them to and from file data." },
  { id: "data", name: "Database (file storage)", color: "#64d2ff", files: ["database/database.py", "students.data"],
    plain: "Reads and writes students.data as JSON. Create, read, update, delete (CRUD)." },
  { id: "utils", name: "Utilities (constants & exceptions)", color: "#8e8e93",
    files: ["utils/constants.py", "utils/exception/admin_controller.py", "utils/exception/database.py",
            "utils/exception/enrolment_exceptions.py", "utils/exception/student_controller.py"],
    plain: "Shared values (menu letters, grade bands, regex) and custom error classes." },
  { id: "tests", name: "Tests", color: "#ff375f", files: ["tests/test_main.py", "tests/test_gui_main.py", "tests/test_database.py"],
    plain: "unittest checks that prove some parts work." },
];

